fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut low = 0;
    let mut high = arr.len();

    // Find the first index where arr[index] >= target.
    while low < high {
        let mid = low + (high - low) / 2;
        if arr[mid] < target {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    // Check if we found the target.
    if low < arr.len() && arr[low] == target {
        Some(low)
    } else {
        None
    }
}

